  1	\chapter{Extracting the Pauli observables}
  2	\label{chap:qpbt-extraction}
  3	% Paper subsection label sec:separating kept for cross-reference fidelity.
  4	\label{sec:separating}
  5	% Source: references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex,
  6	% lines 1415--1877 (subsection ``Pulling the X and Z measurements apart''
  7	% and the closing proof of the soundness theorem).
  8	
  9	This chapter completes the analysis of the Pauli basis test~\cite{Ji2020MIPStar}. Throughout, $(q,m,d)$ is an admissible parameter tuple (Definition~\ref{def:admissible}), $q = 2^t$, and $M = 2^m$ denotes the number of $q$-ary qudits tested for per player. (The letter $M$ also denotes measurement operators, always carrying super- and subscripts; the meaning is determined by context, as in the source.) We fix a projective strategy for the Pauli basis test game $\mathfrak{G}^{\mathrm{Pauli}}_{(q,m,d)}$ that succeeds with probability at least $1-\eps$, in the setting of Chapter~\ref{chap:qpbt-observables}: the shared state $\ket{\psi}$ on registers $\mathrm{A}$, $\mathrm{B}$ is assumed padded with sufficiently many ancilla qubits in the state $\ket{0}$ (Lemma~\ref{lem:projective-strategy-setup} and the convention following it), and $\ket{\hat\psi}$ denotes the expanded state on the six registers $\mathrm{A}\mathrm{A}'\mathrm{A}''\mathrm{B}\mathrm{B}'\mathrm{B}''$, obtained by adjoining to each player the two halves of $M$ pairs $\ket{\mathrm{EPR}_q}$ (Definition~\ref{def:expanded-state}). Unless stated otherwise, every $\approx_\delta$ and $\simeq_\delta$ statement below is taken with respect to the state $\ket{\hat\psi}$, over the question distribution named in the statement, with register placements indicated by subscripts; ``all symmetric equivalents'' refers to the register interchanges of Definition~\ref{def:symmetric-equivalents}.
 10	
 11	We use the following objects from the preceding chapters: the combined point projectors $\hat{M}^{(\mathrm{Point},W),u}_a$ acting on the expanded space (Definition~\ref{def:expanded-point-measurement}); the projective polynomial-pair measurement $\{\hat{S}_{g_X,g_Z}\}$ of Lemma~\ref{lem:qld-4-7}, with outcomes pairs of polynomials in $\mathrm{ideg}_{d,m}(\F_q)$ and error function
 12	\[
 13		\delta_G(\eps,m,d,q) = a(md)^a\bigl(\eps^b + q^{-b} + 2^{-bmd}\bigr)
 14	\]
 15	for universal constants $a > 1$, $0 < b < 1$. This is the error denoted $\delta_S$ in Lemma~\ref{lem:qld-4-7}; we call it $\delta_G$ here to distinguish the global polynomial-pair witness error from the enlarged error used below. We also use the decoding map $\mathrm{Dec} = \mathrm{Dec}_{\F_q}\colon \mathrm{ideg}_{d,m}(\F_q) \to \F_q^{M}$ of the low-degree code (Definition~\ref{def:decoding-map}, applied with $H = \F_q$; see Remark~\ref{rem:qld-decoding-identity}), which maps a polynomial $g$ to the string of its evaluations on the hypercube $\{0,1\}^m$; and the low-degree encoding $h \mapsto g_h$ together with the vectors $\mathrm{ind}_m(u) \in \F_q^M$, characterized by $h \cdot \mathrm{ind}_m(u) = g_h(u)$ for all $u \in \F_q^m$ \eqref{eq:low-degree-encoding-definition}. Both maps are $\F_q$-linear, and $\mathrm{Dec}(g_h) = h$ for every $h \in \F_q^{M}$. We call a polynomial $g \in \mathrm{ideg}_{d,m}(\F_q)$ an \emph{encoding} if $g = g_h$ for some $h \in \F_q^{M}$ or, equivalently, if $g$ is multilinear; since a multilinear polynomial is determined by its values on $\{0,1\}^m$, the encodings are exactly the $g$ with $g_{\mathrm{Dec}(g)} = g$ as polynomial representatives, and
 16	\[
 17		\mathrm{Dec}(g) \cdot \mathrm{ind}_m(u) = g(u)
 18		\qquad \text{for every encoding $g$ and every } u \in \F_q^m\;.
 19	\]
 20	For a $g$ that is not an encoding the two sides of this identity are the evaluations of the distinct polynomial representatives $g_{\mathrm{Dec}(g)}$ and $g$; when $d \leq q-1$ they consequently disagree at some $u$, but when $d \geq q$ the two representatives may induce the same function on $\F_q^m$, so pointwise validity of the identity does not characterize the encodings; see Remark~\ref{rem:qld-decoding-identity}.
 21	
 22	\begin{definition}[Full-field decoding on bounded polynomials]\label{def:qld-full-field-decoder}
 23		\lean{MIPStarRE.QPBT.evalPoly, MIPStarRE.QPBT.decodeOnUniv, MIPStarRE.QPBT.decodeFq}
 24		\lean{MIPStarRE.QPBT.encodingPoly, MIPStarRE.QPBT.IsEncoding}
 25		\leanok
 26		\uses{def:decoding-map, def:low-degree-encoding}
 27		For a bounded polynomial representative $g$, let $\mathrm{Dec}_{\F_q}(g)$ be its evaluations on the Boolean cube, with every value of $\F_q$ retained. For $h \in \F_q^M$, let $g_h$ denote its multilinear encoding. The predicate $\mathrm{IsEncoding}(g)$ asserts the equality $g_{\mathrm{Dec}_{\F_q}(g)}=g$ of polynomial representatives.
 28	\end{definition}
 29	
 30	\begin{lemma}[Linearity and inversion of the full-field decoder]\label{lem:qld-decoder-linearity}
 31		\lean{MIPStarRE.QPBT.decodeFq_add, MIPStarRE.QPBT.decodeFq_smul, MIPStarRE.QPBT.decodeFq_lowDegreeEncoding}
 32		\uses{def:qld-full-field-decoder}
 33		For bounded polynomial representatives $g,g'$ and $c\in\F_q$, one has
 34		\[
 35			\mathrm{Dec}_{\F_q}(g+g')=\mathrm{Dec}_{\F_q}(g)+\mathrm{Dec}_{\F_q}(g'),
 36			\qquad
 37			\mathrm{Dec}_{\F_q}(cg)=c\,\mathrm{Dec}_{\F_q}(g),
 38		\]
 39		and $\mathrm{Dec}_{\F_q}(g_h)=h$ for every $h\in\F_q^M$.
 40	\end{lemma}
 41	
 42	\begin{lemma}[Evaluation identity for encoding outcomes]\label{lem:qld-decoder-evaluation}
 43		\lean{MIPStarRE.QPBT.decodeFq_dotProduct_indicatorVec}
 44		\uses{def:qld-full-field-decoder, def:indicator-vector}
 45		If $g$ is an encoding, then
 46		\[
 47			\mathrm{Dec}_{\F_q}(g)\cdot\mathrm{ind}_m(u)=g(u)
 48		\]
 49		for every $u\in\F_q^m$.
 50	\end{lemma}
 51	
 52	% Local correction of the source (lines 1419 and 1492 of
 53	% 14_analysis_of_the_pauli_basis_test.tex): the source invokes its boolean
 54	% decoding map but describes it as returning all hypercube evaluations, and
 55	% asserts the decoder--encoder identity for every g of individual degree at
 56	% most d. The remark below records the corrected statements.
 57	\begin{remark}[Choice of decoding map and the decoder--encoder identity]\label{rem:qld-decoding-identity}
 58		The source states the constructions of this chapter in terms of its boolean decoding map (the case $H = \{0,1\}$ of Definition~\ref{def:decoding-map}) while describing that map as returning the string of \emph{all} evaluations of $g$ on the hypercube. The proofs require the latter reading, $H = \F_q$, which is adopted throughout this chapter: the linearity of $\mathrm{Dec}$ and the identity $\mathrm{Dec}(g_h) = h$ for all $h \in \F_q^{M}$, both of which fail for the boolean map, are used in the symmetry step of the proof of Lemma~\ref{lem:qld-construct-the-paulis} and in the conjugation identity \eqref{eq:qld-unitary-6}. The source further asserts the identity $\mathrm{Dec}(g) \cdot \mathrm{ind}_m(u) = g(u)$ for every $g \in \mathrm{ideg}_{d,m}(\F_q)$. Since the left-hand side equals $g_{\mathrm{Dec}(g)}(u)$, the identity, taken for all $u \in \F_q^m$, states that the multilinear representative $g_{\mathrm{Dec}(g)}$ and $g$ induce the same function on $\F_q^m$. Every encoding satisfies it, because then $g_{\mathrm{Dec}(g)} = g$ as polynomial representatives; a polynomial that is not an encoding need not: for $m = 1$, $d \geq 2$, and $q > 2$, the polynomial $g(x) = x^2$ has $\mathrm{Dec}(g) \cdot \mathrm{ind}_1(u) = u$, which differs from $g(u) = u^2$ at every $u \notin \{0,1\}$. When $d \leq q-1$ the failure at some $u$ characterizes the polynomials that are not encodings, since evaluation is injective on representatives of individual degree at most $q-1$ (Definition~\ref{def:polynomials-degree}); when $d \geq q$ it does not: for the admissible tuple $(q,m,d) = (8,1,8)$, the polynomial $g(x) = x^8$ is not an encoding, yet $\mathrm{Dec}(g) \cdot \mathrm{ind}_1(u) = u = u^8 = g(u)$ for every $u \in \F_8$. Accordingly, the proofs below invoke the identity only for encodings; in the proof of Lemma~\ref{lem:qld-construct-the-paulis} the contribution of the remaining outcomes is controlled by the bound \eqref{eq:qld-nonencoding-mass} on the mass that the measurement of Lemma~\ref{lem:qld-4-7} places on polynomials that are not encodings, while in the conjugation identity \eqref{eq:qld-unitary-6} the quantity $\mathrm{Dec}(g) \cdot \mathrm{ind}_m(u)$ cancels exactly.
 59	\end{remark}
