 61	\section{The pulled-apart measurements and observables}
 62	
 63	The measurement $\{\hat{S}_{g_X,g_Z}\}$ reads out an $X$-polynomial and a $Z$-polynomial simultaneously. We now separate the two readings again, this time as commuting actions on distinct registers: the polynomial outcome is measured on registers $\mathrm{A}\mathrm{A}'$ (resp.\ $\mathrm{B}\mathrm{B}'$), while a genuine Pauli measurement acts on the EPR register $\mathrm{A}''$ (resp.\ $\mathrm{B}''$).
 64	
 65	\begin{definition}[Single-basis marginals of the polynomial-pair measurement]\label{def:s-w-marginals}
 66		\lean{MIPStarRE.QPBT.GlobalPairWitness.marginalPoly}
 67		\leanok
 68		\uses{lem:qld-4-7}
 69		Let $\{\hat{S}_{g_X,g_Z}\}$ be the projective measurement of Lemma~\ref{lem:qld-4-7}. For every $g \in \mathrm{ideg}_{d,m}(\F_q)$ define
 70		\[
 71			\hat{S}^X_g = \sum_{g_Z} \hat{S}_{g,g_Z}
 72			\qquad \text{and} \qquad
 73			\hat{S}^Z_g = \sum_{g_X} \hat{S}_{g_X,g}\;,
 74		\]
 75		the sums ranging over $\mathrm{ideg}_{d,m}(\F_q)$.
 76	\end{definition}
 77	
 78	\begin{lemma}[Projectivity of the single-basis marginals]\label{lem:s-w-marginals-projective}
 79		\lean{MIPStarRE.QPBT.GlobalPairWitness.marginalPoly_isProjective}
 80		\leanok
 81		\uses{def:s-w-marginals, lem:qld-4-7}
 82		For each $W\in\{X,Z\}$, the family $\{\hat{S}^W_g\}_g$ is a projective measurement with outcomes in $\mathrm{ideg}_{d,m}(\F_q)$.
 83	\end{lemma}
 84	
 85	\begin{definition}[Pauli dot-product projectors]\label{def:tau-dot-product-projector}
 86		\lean{MIPStarRE.QPBT.tauDotProj}
 87		\leanok
 88		\uses{def:generalized-pauli}
 89		For $W \in \{X,Z\}$ and $h \in \F_q^{M}$ let $\tau^W_h$ denote the projector corresponding to measuring $(\C^q)^{\ot M}$ in the $W$ basis and obtaining the outcome $h$ (Definition~\ref{def:generalized-pauli}). For all $W \in \{X,Z\}$, $\tilde{u} \in \F_q^{M}$, and $a \in \F_q$, define the operator
 90		\begin{equation}\label{eq:def-tauwu}
 91			\tau^{W}_{a}(\tilde{u}) = \sum_{h \in \F_q^{M} \,:\, h \cdot \tilde{u} = a} \tau^W_{h}\;.
 92		\end{equation}
 93	\end{definition}
 94	
 95	\begin{lemma}[Projectivity and completeness of the dot-product operators]\label{lem:tau-dot-product-projective}
 96		\lean{MIPStarRE.QPBT.tauDotProj_isProj, MIPStarRE.QPBT.sum_tauDotProj_eq_one}
 97		\leanok
 98		\uses{def:tau-dot-product-projector, def:generalized-pauli}
 99		For each fixed $W$ and $\tilde{u}$, every $\tau^W_a(\tilde{u})$ is a projector and
100		$\sum_{a\in\F_q}\tau^W_a(\tilde{u})=\Id$. Thus
101		$\{\tau^W_a(\tilde{u})\}_{a\in\F_q}$ is a projective measurement.
102	\end{lemma}
103	
104	\begin{definition}[Pulled-apart Pauli basis measurements]\label{def:tilde-m-measurement}
105		\lean{MIPStarRE.QPBT.tildeM}
106		\leanok
107		\uses{def:s-w-marginals, def:tau-dot-product-projector, def:qld-full-field-decoder}
108		For all $W \in \{X,Z\}$ and $\tilde{u} \in \F_q^{M}$ define the measurement $\{\tilde{M}^{W,\tilde{u}}_a\}_{a \in \F_q}$ by
109		\begin{equation}\label{eq:tilde_M}
110			\tilde{M}^{W,\tilde{u}}_a = \sum_{g} \hat{S}^W_g \ot \tau_{(\mathrm{Dec}(g) \cdot \tilde{u}) - a}^W(\tilde{u})\;,
111		\end{equation}
112		the sum ranging over $g \in \mathrm{ideg}_{d,m}(\F_q)$. If $\hat{S}^W_g$ is viewed as an operator acting on registers $\mathrm{A}\mathrm{A}'$ (resp.\ $\mathrm{B}\mathrm{B}'$), then $\tilde{M}^{W,\tilde{u}}_a$ acts on registers $\mathrm{A}\mathrm{A}'\mathrm{A}''$ (resp.\ $\mathrm{B}\mathrm{B}'\mathrm{B}''$), the $\tau^W$ factor acting on $\mathrm{A}''$ (resp.\ $\mathrm{B}''$).
113	\end{definition}
114	
115	\begin{lemma}[Projectivity and completeness of the pulled-apart measurements]\label{lem:tilde-m-projective}
116		\lean{MIPStarRE.QPBT.tildeM_isProj, MIPStarRE.QPBT.sum_tildeM_eq_one}
117		\leanok
118		\uses{def:tilde-m-measurement, lem:s-w-marginals-projective,
119			lem:tau-dot-product-projective}
120		For each $W$ and $\tilde{u}$, every $\tilde{M}^{W,\tilde{u}}_a$ is a projector and
121		$\sum_{a\in\F_q}\tilde{M}^{W,\tilde{u}}_a=\Id$. Thus
122		$\{\tilde{M}^{W,\tilde{u}}_a\}_{a\in\F_q}$ is a projective measurement.
123	\end{lemma}
124	
125	\begin{definition}[Pulled-apart Pauli observables]\label{def:tilde-w-observables}
126		\lean{MIPStarRE.QPBT.tildeObs}
127		\leanok
128		\uses{def:tilde-m-measurement, def:dual-self-dual-normal-basis, def:binary-representation, def:subfield-trace}
129		Let $\{e_j\}_{j \in \{0,\ldots,t-1\}}$ be the self-dual normal basis for $\F_q$ over $\F_2$ (Definition~\ref{def:dual-self-dual-normal-basis}) that is fixed once and for all in Definition~\ref{def:binary-representation}, and let $\tr = \tr_{q \to 2} \colon \F_q \to \F_2$ be the subfield trace. For all $W \in \{X,Z\}$, $\tilde{u} \in \F_q^M$, and $j \in \{0,\ldots,t-1\}$ define the operator
130		\begin{equation}\label{eq:def-tildewj}
131			\tilde{W}^j(\tilde{u}) = \sum_{a \in \F_q} (-1)^{\tr(e_j a)} \, \tilde{M}_a^{W,\tilde{u}}\;,
132		\end{equation}
133		acting on the same registers as $\tilde{M}^{W,\tilde{u}}_a$.
134	\end{definition}
135	
